package dev.cosmerearcanists.hemalurgy;
import dev.cosmerearcanists.compounding.IdentityMath;
import dev.cosmerearcanists.equipment.SpikeItem;
import java.util.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.component.CustomData;
/** Item-owned powers or natural traits. Implantation is separate from extraction. */
public final class HemalurgicSpikes {
    private static final String KEY="cosmerearcanists_hemalurgic_charge";
    public record Charge(UUID id,UUID donor,String metal,String power,List<IdentityMath.Portion> sources,HemalurgicTraits.Senses senses,HemalurgicTraits.Cognition cognition,StolenConnection connection){
        public Charge(UUID id,UUID donor,String metal,String power,List<IdentityMath.Portion> sources){this(id,donor,metal,power,sources,HemalurgicTraits.NONE,HemalurgicTraits.NO_COGNITION,null);}
        public Charge(UUID id,UUID donor,String metal,String power,List<IdentityMath.Portion> sources,HemalurgicTraits.Senses senses){this(id,donor,metal,power,sources,senses,HemalurgicTraits.NO_COGNITION,null);}
        public Charge(UUID id,UUID donor,String metal,String power,List<IdentityMath.Portion> sources,HemalurgicTraits.Senses senses,HemalurgicTraits.Cognition cognition){this(id,donor,metal,power,sources,senses,cognition,null);}
        public Charge{Objects.requireNonNull(id);Objects.requireNonNull(donor);Objects.requireNonNull(metal);Objects.requireNonNull(power);Objects.requireNonNull(senses);Objects.requireNonNull(cognition);sources=List.copyOf(sources);double sum=sources.stream().mapToDouble(IdentityMath.Portion::strength).sum();boolean magical=HemalurgyRules.accepts(metal,power),iron=metal.equals("iron")&&power.equals(HemalurgicTraits.STRENGTH),tin=metal.equals("tin")&&power.equals(HemalurgicTraits.SENSES);boolean zinc=metal.equals("zinc")&&power.equals(HemalurgicTraits.FORTITUDE),copper=metal.equals("copper")&&power.equals(HemalurgicTraits.MEMORY);if((zinc||copper)&&(Math.abs(sum-cognition.resistance())>1e-8||cognition.resistance()<=0||zinc&&cognition.memoryCapacity()!=0||copper&&(cognition.resistance()<.05||cognition.resistance()>.25||Math.abs(cognition.memoryCapacity()-3*cognition.resistance())>1e-8))||!zinc&&!copper&&!cognition.equals(HemalurgicTraits.NO_COGNITION))throw new IllegalArgumentException("Invalid mental trait");boolean duralumin=metal.equals("duralumin")&&power.equals(DuraluminTheft.POWER);if(duralumin?(connection==null||sources.size()!=1||sum!=1||!connection.identity().equals(sources.get(0).identity())):connection!=null)throw new IllegalArgumentException("Invalid Identity contents");if(!(magical||iron||tin||zinc||copper||duralumin)||sources.isEmpty()||sources.size()>64||!Double.isFinite(sum)||sum<=0||magical&&sum>1024||!tin&&!senses.equals(HemalurgicTraits.NONE)||tin&&(senses.maximum()<=0||Math.abs(sum-senses.maximum())>1e-8))throw new IllegalArgumentException("Invalid spike contents");}
        public double strength(){return sources.stream().mapToDouble(IdentityMath.Portion::strength).sum();}
        public boolean trait(){return power.startsWith("trait:");}
    }
    public static String label(Charge charge){return charge.power().equals(DuraluminTheft.POWER)?"Connection and Identity":charge.power().equals(HemalurgicTraits.FORTITUDE)?"Mental fortitude":charge.power().equals(HemalurgicTraits.MEMORY)?"Mental strength and memory":charge.power().equals(HemalurgicTraits.STRENGTH)?"Physical strength":charge.power().equals(HemalurgicTraits.SENSES)?"Natural senses":dev.cosmerearcanists.nicrosil.NicrosilPowers.label(charge.power());}
    public static boolean marked(ItemStack stack){return stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().contains(KEY);}
    public static Charge contents(ItemStack stack){if(!(stack.getItem() instanceof SpikeItem spike)||stack.getCount()!=1)return null;var root=stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getCompound(KEY);int schema=root.getInt("schema");if((schema!=1&&schema!=2&&schema!=3)||!root.hasUUID("id")||!root.hasUUID("donor")||!root.getString("metal").equals(spike.metal))return null;try{var list=root.getList("sources",Tag.TAG_COMPOUND);if(list.size()>64)return null;var sources=new ArrayList<IdentityMath.Portion>();for(int i=0;i<list.size();i++){var t=list.getCompound(i);sources.add(new IdentityMath.Portion(t.hasUUID("identity")?t.getUUID("identity"):null,t.getDouble("strength")));}var senses=root.getCompound("senses");var profile=schema>=2?new HemalurgicTraits.Senses(senses.getDouble("sight"),senses.getDouble("hearing"),senses.getDouble("touch")):HemalurgicTraits.NONE;return new Charge(root.getUUID("id"),root.getUUID("donor"),spike.metal,root.getString("power"),sources,profile,new HemalurgicTraits.Cognition(root.getDouble("resistance"),root.getDouble("memory_capacity")),schema>=3&&root.contains("connection")?StolenConnection.load(root.getCompound("connection")):null);}catch(IllegalArgumentException e){return null;}}
    public static boolean store(ItemStack stack,Charge charge){if(stack.getCount()!=1||!(stack.getItem() instanceof SpikeItem spike)||!spike.metal.equals(charge.metal())||marked(stack))return false;var tag=new CompoundTag();tag.putInt("schema",3);if(charge.connection()!=null)tag.put("connection",charge.connection().save());tag.putUUID("id",charge.id());tag.putUUID("donor",charge.donor());tag.putString("metal",charge.metal());tag.putString("power",charge.power());tag.putDouble("resistance",charge.cognition().resistance());tag.putDouble("memory_capacity",charge.cognition().memoryCapacity());var parts=new ListTag();for(var source:charge.sources()){var t=new CompoundTag();if(source.identity()!=null)t.putUUID("identity",source.identity());t.putDouble("strength",source.strength());parts.add(t);}tag.put("sources",parts);if(charge.power().equals(HemalurgicTraits.SENSES)){var senses=new CompoundTag();senses.putDouble("sight",charge.senses().sight());senses.putDouble("hearing",charge.senses().hearing());senses.putDouble("touch",charge.senses().touch());tag.put("senses",senses);}var root=stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();root.put(KEY,tag);stack.set(DataComponents.MAX_STACK_SIZE,1);stack.set(DataComponents.CUSTOM_DATA,CustomData.of(root));return true;}
    private HemalurgicSpikes(){}
}
